<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Models\Appointment;
use Illuminate\Http\Request;
class AppointmentController extends Controller { private array $with=['customer','address','equipment','technician','workOrder']; public function index(Request $request){$query=Appointment::with($this->with)->when($request->date,fn($q,$v)=>$q->whereDate('scheduled_at',$v))->when($request->status,fn($q,$v)=>$q->where('status',$v))->when($request->technician_id,fn($q,$v)=>$q->where('technician_id',$v));if($request->user()->role==='technician')$query->where('technician_id',$request->user()->employee?->id);return $query->orderBy('scheduled_at')->paginate(100);} public function store(Request $request){$data=$request->validate(['customer_id'=>'required|exists:customers,id','address_id'=>'required|exists:customer_addresses,id','equipment_id'=>'nullable|exists:customer_equipment,id','technician_id'=>'nullable|exists:employees,id','scheduled_at'=>'required|date','duration_minutes'=>'required|integer|min:15','type'=>'required|string|max:80','notes'=>'nullable|string']);$appointment=Appointment::create($data);return response()->json(['data'=>$appointment->load($this->with)],201);} public function update(Request $request,Appointment $appointment){$appointment->update($request->validate(['technician_id'=>'sometimes|nullable|exists:employees,id','scheduled_at'=>'sometimes|date','duration_minutes'=>'sometimes|integer|min:15','type'=>'sometimes|string','notes'=>'nullable|string','status'=>'sometimes|in:scheduled,confirmed,traveling,arrived,in_service,awaiting_approval,completed,cancelled']));return response()->json(['data'=>$appointment->load($this->with)]);} public function destroy(Appointment $appointment){$appointment->delete();return response()->noContent();} }
